/**
 * Shape of `src/data/repos.json`, generated by `scripts/fetch-repos.ts`.
 */

export interface Repo {
  /** Repository name, e.g. `loop`. */
  name: string;
  /** Repository description on GitHub, if set. */
  description: string | null;
  /** Website from the repository settings. Starts with `pagesPrefix`. */
  homepage: string;
  /** Repository URL on GitHub. */
  url: string;
  /** Time of the last push to the repository. */
  pushedAt: string;
  /** Primary language reported by GitHub, if any. */
  language: string | null;
  stars: number;
  archived: boolean;
  fork: boolean;
}

export interface RepoData {
  /** When the data was fetched from GitHub. */
  fetchedAt: string;
  /** GitHub user whose repositories were listed. */
  owner: string;
  /** Number of repositories the user has in total. */
  totalRepos: number;
  /** Repositories with a website under `pagesPrefix`, newest push first. */
  repos: Repo[];
}

/** Path of a repo on this site without a trailing slash, e.g. `/loop`. */
export function pagePath(repo: Repo): string {
  return new URL(repo.homepage).pathname.replace(/\/+$/, '');
}
